#!/usr/bin/env bash
# check-author-policy.sh — enforce the single-human-contributor policy (§13, §43).
#
# What is forbidden:
#   - any human author/committer identity outside the authorized human set below;
#   - AI coding identities (Claude, Codex, ChatGPT, Copilot, Gemini, Kimi, …);
#   - contribution trailers (Co-authored-by, Generated-by, …);
#   - AI-attribution phrases ("generated by/with …", "AI-generated", session trailers).
#
# The canonical human identity is ZEKRITI Tarek. The exact MEMOPERF
# <contact@checkupauto.fr> Git identity is accepted as the connector-authored
# technical alias for that same authorized human so provenance can be preserved
# without rewriting existing commits. No other human alias is accepted.
#
# Ordinary GitHub automation bots remain allowed: an identity must use a name
# ending in `[bot]` and a GitHub noreply address. AI coding-bot names are still
# rejected by IDENTITY_RE below. This keeps Dependabot/CI provenance intact
# without widening the set of authorized humans.
#
# What is ALLOWED: technical references to model providers (Anthropic, OpenAI,
# Ollama, …) — the project ships provider adapters (mission §30). Attribution
# is forbidden, interoperability is not.
#
# MERGE COMMITS ARE SKIPPED. A pull request merged through GitHub's UI produces
# a merge commit authored by the account that clicked the button and committed
# by "GitHub" — an identity no contributor can influence and that can never
# equal the canonical identity. Checking them made the policy unsatisfiable:
# the commits being merged are still each checked, so skipping merge commits
# costs no authored-content coverage.
#
# Usage:
#   scripts/check-author-policy.sh           # check HEAD commit
#   scripts/check-author-policy.sh A..B      # check a commit range
set -euo pipefail
cd "$(dirname "$0")/.."

RANGE="${1:-HEAD}"
CANONICAL_NAME="ZEKRITI Tarek"
CONNECTOR_ALIAS_NAME="MEMOPERF"
CONNECTOR_ALIAS_EMAIL="contact@checkupauto.fr"

IDENTITY_RE='claude|anthropic|chatgpt|codex|copilot|gemini|kimi|opencode|noreply@anthropic'
TRAILER_RE='^(co-?authored-by|co-developed-by|contributed-by|generated-by|assisted-by|suggested-by|[a-z-]*-session)\s*:'
ATTRIBUTION_RE='generated (by|with) (claude|chatgpt|codex|copilot|gemini|kimi|opencode|ai)|ai[- ]generated|ai[- ]assisted|written by (claude|chatgpt|codex|kimi|ai)'

is_authorized_human() {
  local name="$1"
  local email="$2"
  if [ "$name" = "$CANONICAL_NAME" ]; then
    return 0
  fi
  [ "$name" = "$CONNECTOR_ALIAS_NAME" ] && [ "$email" = "$CONNECTOR_ALIAS_EMAIL" ]
}

is_allowed_automation_bot() {
  local name="$1"
  local email="$2"
  [[ "$name" == *"[bot]" ]] && [[ "$email" == *"@users.noreply.github.com" ]]
}

is_authorized_identity() {
  is_authorized_human "$1" "$2" || is_allowed_automation_bot "$1" "$2"
}

fail=0
while IFS=$'\t' read -r h an ae cn ce; do
  if ! is_authorized_identity "$an" "$ae" || ! is_authorized_identity "$cn" "$ce"; then
    echo "::error::$h author/committer identity is outside the single-human-plus-automation policy"
    fail=1
  fi
  if echo "$an$ae$cn$ce" | grep -Eiq "$IDENTITY_RE"; then
    echo "::error::$h AI coding identity detected"
    fail=1
  fi
  if git log -1 --format='%B' "$h" | grep -Eiq "$TRAILER_RE"; then
    echo "::error::$h forbidden contribution trailer"
    fail=1
  fi
  if git log -1 --format='%B' "$h" | grep -Eiq "$ATTRIBUTION_RE"; then
    echo "::error::$h AI attribution phrase in commit message"
    fail=1
  fi
done < <(git log --no-merges --format='%H%x09%an%x09%ae%x09%cn%x09%ce' "$RANGE")

if [ "$fail" -ne 0 ]; then
  echo "AUTHOR POLICY: FAILED"
  exit 1
fi
echo "AUTHOR POLICY: PASS ($RANGE)"
